(()=>{const s=document.createElement('style');s.textContent=`.microscope-instruction{position:relative;z-index:6;margin:0 auto 24px;width:max-content;max-width:calc(100% - 32px);padding:10px 18px;border:2px solid #ffffffb8;border-radius:999px;background:#063b78a8;backdrop-filter:blur(10px);color:#fff;text-align:center;font-size:14px;font-weight:900;box-shadow:0 0 18px #00d9ff66}.microscope-lens{position:fixed;z-index:10000;width:min(390px,78vw);height:min(390px,78vw);border-radius:50%;pointer-events:none;opacity:0;overflow:hidden;transform:translate(-50%,-50%) scale(.65);transition:.2s;background:radial-gradient(circle at 38% 34%,#ffffff20 0 7%,transparent 22%),radial-gradient(circle,transparent 62%,#001b3a88 80%,#001020e8 100%);border:8px solid #fff;box-shadow:0 0 0 8px #008cff,0 0 46px #00d9ff,0 0 62px #ff8a0080}.microscope-lens.active{opacity:1;transform:translate(-50%,-50%) scale(1)}.microscope-view{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:38px;text-align:center;color:#fff}.microscope-copy{font-size:clamp(34px,7vw,72px);line-height:1.05;font-weight:1000;letter-spacing:-1px;text-shadow:0 2px 6px #001b3a;transform:scale(1.35);max-width:100%;overflow-wrap:anywhere}.microscope-cross-v,.microscope-cross-h{position:absolute;background:#ffffff8c;pointer-events:none}.microscope-cross-v{width:1px;height:100%;left:50%;top:0}.microscope-cross-h{height:1px;width:100%;top:50%;left:0}.microscope-label{position:absolute;left:50%;bottom:9%;transform:translateX(-50%);padding:5px 10px;border-radius:999px;background:#001f45df;color:#fff;font-size:11px;font-weight:900;letter-spacing:1px;white-space:nowrap}.microscope-popup{position:fixed;z-index:10002;left:50%;top:50%;transform:translate(-50%,-50%) scale(.55) rotate(-7deg);opacity:0;pointer-events:none;transition:.22s ease}.microscope-popup.show{opacity:1;transform:translate(-50%,-50%) scale(1) rotate(0)}.microscope-popup svg{width:min(260px,60vw);height:auto;filter:drop-shadow(0 0 10px #fff) drop-shadow(0 0 22px #00d9ff) drop-shadow(0 0 18px #ff8a00)}.microscope-popup-text{margin-top:8px;text-align:center;color:#fff;font-weight:1000;letter-spacing:1.5px;text-shadow:0 0 10px #00d9ff,0 0 16px #ff8a00}.lab-glass{position:relative!important;background:linear-gradient(135deg,rgba(255,255,255,.62),rgba(220,244,255,.28))!important;border:1px solid rgba(255,255,255,.88)!important;box-shadow:0 18px 48px rgba(0,72,145,.16),inset 0 1px 0 rgba(255,255,255,.95),inset 0 0 28px rgba(0,174,255,.07)!important;backdrop-filter:blur(18px) saturate(145%)!important;-webkit-backdrop-filter:blur(18px) saturate(145%)!important;overflow:hidden}.lab-glass:after{content:"";position:absolute;pointer-events:none;z-index:0;left:-20%;top:-65%;width:65%;height:190%;transform:rotate(22deg);background:linear-gradient(90deg,transparent,rgba(255,255,255,.32),transparent);transition:transform .7s ease}.lab-glass:hover:after{transform:translateX(190%) rotate(22deg)}.lab-glass>*{position:relative;z-index:1}.summary-card.lab-glass,.research-person.lab-glass{border-color:rgba(72,190,255,.42)!important}.info-card.lab-glass{background:linear-gradient(135deg,rgba(255,255,255,.94),rgba(225,247,255,.82))!important;border:5px solid rgba(9,46,93,.88)!important}.lab-glass-dark{background:linear-gradient(135deg,rgba(4,65,132,.48),rgba(0,140,255,.18))!important;border:1px solid rgba(255,255,255,.55)!important;box-shadow:0 18px 45px rgba(0,31,75,.25),inset 0 1px 0 rgba(255,255,255,.38)!important;backdrop-filter:blur(16px) saturate(145%)!important;-webkit-backdrop-filter:blur(16px) saturate(145%)!important}.microscope-active,.microscope-active *{-webkit-user-select:none!important;user-select:none!important;-webkit-touch-callout:none!important}.microscope-active ::selection{background:transparent;color:inherit}@media(max-width:760px){.microscope-instruction{font-size:12px;padding:8px 13px}.microscope-copy{font-size:clamp(30px,12vw,58px);transform:scale(1.22)}.lab-glass{backdrop-filter:blur(12px) saturate(130%)!important;-webkit-backdrop-filter:blur(12px) saturate(130%)!important}}`;document.head.appendChild(s);function addGlass(){document.querySelectorAll('.summary-card,.research-person,.info-card').forEach(e=>e.classList.add('lab-glass'));document.querySelectorAll('.molecule-link,.hero-verse').forEach(e=>e.classList.add('lab-glass-dark'))}addGlass();const hero=document.querySelector('.hero');if(hero){const note=document.createElement('div');note.className='microscope-instruction lab-glass-dark';note.textContent='Hold the screen or mouse to enter microscope mode.';hero.insertBefore(note,hero.firstChild)}const lens=document.createElement('div');lens.className='microscope-lens';lens.innerHTML='<div class="microscope-view"><div class="microscope-copy"></div></div><i class="microscope-cross-v"></i><i class="microscope-cross-h"></i><span class="microscope-label">MICROSCOPE MODE</span>';document.body.appendChild(lens);const copy=lens.querySelector('.microscope-copy');const popup=document.createElement('div');popup.className='microscope-popup';popup.innerHTML='<svg viewBox="0 0 220 220" aria-hidden="true"><g fill="none" stroke="#ffffff" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"><path d="M94 29h38l8 35-30 7z" fill="#008cff"/><path d="M112 70l-19 44"/><path d="M89 116c18 8 40 4 54-12"/><path d="M132 88c28 14 34 48 20 72"/><path d="M71 165h90"/><path d="M83 165c5-21 20-34 41-39"/><path d="M68 55l23 10"/><circle cx="87" cy="124" r="10" fill="#ff8a00"/></g></svg><div class="microscope-popup-text">ENTERING MICROSCOPE MODE</div>';document.body.appendChild(popup);let holding=false,timer=null,lastEvent=null;const selector='h1,h2,h3,p,.eyebrow,.kicker,.credit-label,.institution,.hero-verse,.molecule-link,.paper-button,.comic-panel span,.bottom-band,footer';function exactTextAt(x,y){let range=null;if(document.caretRangeFromPoint)range=document.caretRangeFromPoint(x,y);else if(document.caretPositionFromPoint){const p=document.caretPositionFromPoint(x,y);if(p){range=document.createRange();range.setStart(p.offsetNode,p.offset);range.collapse(true)}}if(!range||!range.startContainer||range.startContainer.nodeType!==Node.TEXT_NODE)return'';const text=range.startContainer.textContent||'';let i=Math.min(range.startOffset,text.length-1);if(i<0)return'';while(i>0&&/\s/.test(text[i]))i--;let a=i,b=i;while(a>0&&!/\s/.test(text[a-1]))a--;while(b<text.length&&!/\s/.test(text[b]))b++;let phrase=text.slice(Math.max(0,a-18),Math.min(text.length,b+18)).trim();if(!phrase)phrase=text.trim();return phrase}function update(e){lastEvent=e;lens.style.left=e.clientX+'px';lens.style.top=e.clientY+'px';if(!holding)return;const el=document.elementFromPoint(e.clientX,e.clientY);const valid=el&&el.closest(selector);const t=valid?exactTextAt(e.clientX,e.clientY):'';copy.textContent=t||((valid&&valid.textContent)?valid.textContent.trim().slice(0,80):'')}function clearSelection(){const sel=window.getSelection&&window.getSelection();if(sel&&sel.removeAllRanges)sel.removeAllRanges()}function activate(){popup.classList.remove('show');if(lastEvent)update(lastEvent);lens.classList.add('active');document.body.classList.add('microscope-active');clearSelection()}function start(e){if(e.button!==undefined&&e.button!==0)return;if(e.target.closest('a,button,.info-card'))return;holding=true;lastEvent=e;clearSelection();popup.classList.add('show');document.body.classList.add('microscope-active');timer=setTimeout(()=>{if(holding)activate()},500)}function stop(){holding=false;clearTimeout(timer);popup.classList.remove('show');lens.classList.remove('active');document.body.classList.remove('microscope-active');clearSelection();copy.textContent=''}document.addEventListener('selectstart',e=>{if(document.body.classList.contains('microscope-active'))e.preventDefault()});document.addEventListener('copy',e=>{if(document.body.classList.contains('microscope-active'))e.preventDefault()});document.addEventListener('cut',e=>{if(document.body.classList.contains('microscope-active'))e.preventDefault()});addEventListener('pointermove',update,{passive:true});addEventListener('pointerdown',start,{passive:true});addEventListener('pointerup',stop,{passive:true});addEventListener('pointercancel',stop,{passive:true})})();